changeSet.sql:
ALTER TABLE unique_equipment ADD COLUMN system_type VARCHAR(200);
ALTER TABLE unique_equipment ADD COLUMN equip_key VARCHAR(900);
-- бэкфилл: существующие ключи были без системы → equip_key = прежний norm_key
UPDATE unique_equipment SET equip_key = norm_key WHERE equip_key IS NULL;
CREATE INDEX idx_unique_equipment_equip_key ON unique_equipment(equip_key);
